const raw=$json.payload; const m=(typeof raw==='string')?JSON.parse(raw):raw;
const ov=($('Aggregate Overdue').first()||{json:{}}).json||{};
const token=$('Get Lark Token').first().json.tenant_access_token;
const fmt=n=>(n===null||n===undefined)?'—':Number(n).toLocaleString('en-US');
const money=n=>(n===null||n===undefined)?'—':'S$'+Number(n).toLocaleString('en-US');
const moneyK=n=>(n===null||n===undefined)?'—':(n>=1000?'S$'+Math.round(n/1000)+'k':money(n));
const sign=p=>(p===null||p===undefined)?'':((p>=0?'+':'')+p+'%');
const flag=cc=>cc?cc.toUpperCase().replace(/./g,c=>String.fromCodePoint(127397+c.charCodeAt(0))):'';
const FBc={Singapore:'SG',Malaysia:'MY',Indonesia:'ID'};
const MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const fmtDate=s=>{const d=new Date(String(s).substring(0,10)+'T00:00:00Z');return d.getUTCDate()+' '+MON[d.getUTCMonth()];};
const days=Math.round((new Date(String(m.period_end).substring(0,10))-new Date(String(m.period_start).substring(0,10)))/86400000);
const periodLabel=days<=1?'day-over-day':('~'+Math.round(days/7)+' wks');
const overduePct=(m.ar_overdue&&m.ar_outstanding)?Math.round(m.ar_overdue/m.ar_outstanding*100):null;
const CO=['Singapore','Malaysia','Indonesia'];
const platO={Instagram:0,TikTok:1,Facebook:2}; const platS={Instagram:'IG',TikTok:'TT',Facebook:'FB'};
const sp=p=>p==='Koocester'?'Main':String(p).replace('Koocester ','');
const gp=m.geo_page||[], gpl=m.geo_plat||[]; const cby={}; (m.ctot||[]).forEach(c=>cby[c.country]=c);
let aud=''; const mt=m.main_total||{};
const mp=(m.main||[]).slice().sort((a,b)=>(platO[a.platform]??9)-(platO[b.platform]??9));
aud+='
🌏 Koocester (Regional flagship): '+fmt(mt.f)+' ('+sign(mt.pct)+')
   '+mp.map(x=>platS[x.platform]+' '+fmt(x.f)+' ('+sign(x.pct)+')').join(' · ')+'
';
CO.forEach(cn=>{const ct=cby[cn]; if(!ct) return; aud+='
'+flag(FBc[cn])+' '+cn+': '+fmt(ct.f)+' ('+sign(ct.pct)+')
'; const pgs=gp.filter(x=>x.country===cn).sort((a,b)=>(b.f||0)-(a.f||0)); pgs.forEach(pg=>{const pl=gpl.filter(x=>x.country===cn&&x.page===pg.page).sort((a,b)=>(platO[a.platform]??9)-(platO[b.platform]??9)); const ps=pl.map(x=>platS[x.platform]+' '+fmt(x.f)+' ('+sign(x.pct)+')').join(' · '); aud+='   • '+sp(pg.page)+' '+fmt(pg.f)+' ('+sign(pg.pct)+') — '+ps+'
';});});
const wonLine=(m.won_by_market&&m.won_by_market.length)?'• Won by market (all-time): '+m.won_by_market.map(w=>flag(FBc[w.market])+' '+moneyK(w.won)).join(' · ')+'
':'';
const spendLine=(m.top_spend&&m.top_spend.length)?'• Top spend (7d): '+m.top_spend.map(s=>String(s.cat).substring(0,20)+' '+money(s.amt)).join(' · ')+'
':'';
const spenderLine=(m.top_spenders&&m.top_spenders.length)?'• Top card spender (7d): '+m.top_spenders.map(s=>String(s.who).split(' ').slice(0,2).join(' ')+' '+money(s.amt)).join(' · ')+'  (card-tagged only)
':'';
const top=m.top_reel?String(m.top_reel).substring(0,60):'—';
const opsLine=ov.bottleneckLine||'';
const header='📊 Koocester Daily Brief — '+fmtDate(m.period_end)+' '+String(m.period_end).substring(0,4);
const baseText='💰 FINANCE
'+'• Collected (MTD): '+money(m.collected_mtd)+'
'+'• Invoiced (MTD): '+money(m.invoiced_mtd)+'
'+'• AR outstanding: '+money(m.ar_outstanding)+'  (overdue '+money(m.ar_overdue)+' ⚠️ '+overduePct+'%)
'+'• Open pipeline: '+money(m.open_pipeline)+'
'+wonLine+'• Aspire balance: '+money(m.aspire_balance)+'  (card float)
'+'• Card spend (7d): '+money(m.card_spend_7d)+'
'+spendLine+spenderLine+'• Runway: not yet real — needs primary-bank balance + payroll feed (Aspire = card only)

'+'🎯 SALES
'+'• New leads (MTD): '+fmt(m.leads_mtd)+'
'+'• New deals (7d): '+fmt(m.deals_7d)+'

'+'📱 AUDIENCE  ('+periodLabel+')
'+'• Total network: '+fmt(m.total_followers)+' ('+sign(m.follower_growth_pct)+')
'+aud+'
'+'🎬 CONTENT
'+'• Reach (7d): '+fmt(m.reach_7d)+' views
'+'• Avg engagement (30d): '+m.eng_30d+'%
'+'   Target ladder → 6% (your current top-10%) · 8%+ world-class leader · 10%+ hero (your best reels hit 10–18%)
'+'• 🏆 Top reel (7d): '+top+' · '+fmt(m.top_reel_views)+' views
'+'   '+(m.top_reel_url||'')+(opsLine?'

⚙️ OPS
• '+opsLine:'');
const prompt="You are the founder-CEO's chief of staff at Koocester, a LEAN luxury-media company. Hakim is the founder AND CEO — there is NO CFO, NO AR manager, NO separate sales lead to 'schedule with'. Do NOT invent roles or tell him to brief himself. Name only real people/stages given below. — north star: become the world's #1 most trusted and influential media, then convert trust into lead-gen + recurring revenue. Output PLAIN TEXT ONLY — no markdown/asterisks. Two parts:

⚡ TODAY (ranked — do #1 first):
1. <single highest-leverage action — name the number/page/person + a deadline>
2. <next>
3. <next>
4. <next>
5. <next>

📈 Working: <one line, the strongest real momentum to double down on>

Rules: each numbered item <=24 words, an ACTION verb-first with a concrete number + deadline. Finance and cash discipline outrank vanity metrics. NEVER use asterisks or any markdown. Deduplicate.

The 5 must be DISTINCT and span DIFFERENT domains — do NOT make more than one about collections. Pick the 5 highest-leverage from these REAL levers:
- CASH: chase "+money(m.ar_overdue)+" overdue AR ("+overduePct+"% of AR), top 5 debtors; only "+money(m.collected_mtd)+" collected MTD.
- CONTENT BOTTLENECK: "+((ov&&ov.overdueTotal)||0)+" videos overdue; biggest jam "+((ov&&ov.topStr)||'Strategist QC')+". QC is owned by just 2 strategists (Wendi + Audrey) — a capacity wall; unblock or add a 3rd QC hand.
- CONVERSION: lead->customer is UNINSTRUMENTED ("+fmt(m.leads_mtd)+" leads MTD, "+fmt(m.deals_7d)+" deals 7d) — spec HubSpot client_account + lifecycle to expose the funnel.
- SCALE: the Business page compounds across all 3 markets — reverse-engineer its format and brief every vertical.
- ENGAGEMENT: 30d "+m.eng_30d+"% vs world-class 8%+ — test the top-reel format across pages.
Each numbered item <=24 words, verb-first, with a real number + owner/stage. No invented roles. No markdown.";
return [{ json: { header, baseText, prompt, token } }];

let insight='';
try { const ai=$json; if (ai && ai.content) insight=ai.content.map(c=>c.text||'').join('').trim().replace(/\*/g,''); } catch(e){ insight=''; }
const c=$('Compose').first().json;
const full=c.header+'

'+(insight?insight+'

':'')+c.baseText+'

— Auto-generated from live data. Reply for tweaks.';
const content=JSON.stringify({ text: full });
return [{ json: { content, token: c.token } }];

const items = ($json.data && $json.data.items) || [];
const txt = (v)=>{ if(v&&typeof v==='object'){const val=v.value; if(Array.isArray(val)&&val.length){const x=val[0]; return (x&&x.text)?x.text:x;} return null;} return v; };
let total=0; const byStage={};
for(const r of items){ const fl=r.fields||{};
  const gen=txt(fl['Overdue'])==='OVERDUE';
  const edit=txt(fl['Overdue (alert)'])==='OVERDUE';
  const raw=txt(fl['Raw Upload Overdue (alert)'])==='OVERDUE';
  const amend=txt(fl['Amendments Overdue (alert)'])==='OVERDUE';
  if(!(gen||edit||raw||amend)) continue;
  total++;
  let bucket;
  if(edit) bucket='Editing';
  else if(raw) bucket='Raw footage';
  else if(amend) bucket='Amendments';
  else { bucket = txt(fl['Video Stage']) || 'Other'; }
  byStage[bucket]=(byStage[bucket]||0)+1;
}
const top=Object.entries(byStage).sort((a,b)=>b[1]-a[1]);
const topStr=top.slice(0,3).map(([n,c])=>n+' '+c).join(', ');
const bottleneckLine = total>0 ? (total+' videos overdue company-wide — top jams: '+topStr) : 'No overdue videos — clean.';
return [{ json: { overdueTotal: total, topStr, byStage, bottleneckLine } }];

const token=$('Get Lark Token').first().json.tenant_access_token;
const base='BG8PbaZFna1NQksNWkglTN85gSf';
const tbl='tbl8wIByJQwhIUei';
const CTBL='tblnMZctdGYfXjYL';
const url='https://open.larksuite.com/open-apis/bitable/v1/apps/'+base+'/tables/'+tbl+'/records/search';
const curl='https://open.larksuite.com/open-apis/bitable/v1/apps/'+base+'/tables/'+CTBL+'/records/search';
const H={Authorization:'Bearer '+token};
const cnt=async(f,v)=>{ try{ const r=await this.helpers.httpRequest({method:'POST',url:url+'?page_size=1',headers:H,body:{field_names:['Video Stage'],filter:{conjunction:'and',conditions:[{field_name:f,operator:'is',value:[v]}]}},json:true}); return (r&&r.data&&r.data.total)||0; }catch(e){ return null; } };
const cnc=async(f,v)=>{ try{ const r=await this.helpers.httpRequest({method:'POST',url:curl+'?page_size=1',headers:H,body:{field_names:['Carousel Stage'],filter:{conjunction:'and',conditions:[{field_name:f,operator:'is',value:[v]}]}},json:true}); return (r&&r.data&&r.data.total)||0; }catch(e){ return null; } };
const src=await cnt('Video Stage','Sourcing');
const rts=await cnt('Video Stage','Ready to Shoot');
const plan=await cnt('Video Stage','Planning');
const qc=await cnt('Video Stage','Strategist QC');
const rte=await cnt('Video Stage','Ready to Edit');
const edit=await cnt('Video Stage','Editing');
const ready=await cnt('Video Stage','Ready To Upload');
const ns=await cnt('Video Stage','Not Started');
const appr=await cnt('Video Stage','Approval');
const finappr=await cnt('Video Stage','Final Approval (Marketing/Client)');
const ov=await cnt('Overdue','OVERDUE');
const gates=((appr||0)+(finappr||0));
const cNs=await cnc('Carousel Stage','Not Started');
const cCw=await cnc('Carousel Stage','Copywriting');
const cFa=await cnc('Carousel Stage','Final Approval (Head Copywriter/Client)');
const cReady=await cnc('Carousel Stage','Ready to Upload');
const cOv=await cnc('Overdue','OVERDUE');
let unsched=null;
try{ const r=await this.helpers.httpRequest({method:'POST',url:url+'?page_size=1',headers:H,body:{field_names:['Video Stage'],filter:{conjunction:'and',conditions:[{field_name:'Video Stage',operator:'is',value:['Ready To Upload']},{field_name:'Intended Upload Date',operator:'isEmpty',value:[]}]}},json:true}); unsched=(r&&r.data&&r.data.total)||0; }catch(e){ unsched=null; }
let pageMap={};
try{
  const pr=await this.helpers.httpRequest({method:'POST',url:'https://open.larksuite.com/open-apis/bitable/v1/apps/'+base+'/tables/tblUscIBwxElzzXi/records/search?page_size=500',headers:H,body:{field_names:['Page']},json:true});
  const pit=(pr&&pr.data&&pr.data.items)||[];
  for(const it of pit){ const f=it.fields&&it.fields.Page; let nm=null; if(typeof f==='string') nm=f; else if(Array.isArray(f)) nm=(f[0]&&(f[0].text||f[0].name))||null; else if(f&&typeof f==='object') nm=f.text||null; pageMap[it.record_id]=(nm||it.record_id).trim(); }
}catch(e){ pageMap=null; }
let atPage=[],atPerson=[];
try{
  const r=await this.helpers.httpRequest({method:'POST',url:url+'?page_size=500',headers:H,body:{field_names:['Page','Video Stage','Strategist','Video Editor','Producer','Social Media Manager','Head of Growth Approver'],filter:{conjunction:'and',conditions:[{field_name:'Overdue',operator:'is',value:['OVERDUE']}]}},json:true});
  const items=(r&&r.data&&r.data.items)||[];
  const pT={},qT={};
  for(const it of items){ const f=it.fields||{};
    const p=f.Page; let rid=(p&&Array.isArray(p.link_record_ids))?p.link_record_ids[0]:((Array.isArray(p)&&p[0]&&p[0].record_ids&&p[0].record_ids[0])||null); const pn=(rid&&pageMap&&pageMap[rid])||'(no page)'; pT[pn]=(pT[pn]||0)+1;
    const st=f['Video Stage']; let pick;
    if(st==='Strategist QC'||st==='Planning') pick=f.Strategist;
    else if(st==='Amendments Needed'||st==='Amendments (Marketing)'||st==='Editing') pick=f['Video Editor'];
    else if(st==='Approval'||st==='Final Approval (Marketing/Client)') pick=f['Head of Growth Approver'];
    else if(st==='Sourcing'||st==='Ready to Shoot'||st==='Ready to Edit') pick=f.Producer;
    else if(st==='Ready To Upload') pick=f['Social Media Manager'];
    let nm=(Array.isArray(pick)&&pick[0]&&pick[0].name)||null; if(!nm) nm='(unassigned)'; qT[nm]=(qT[nm]||0)+1; }
  atPage=Object.entries(pT).sort((a,b)=>b[1]-a[1]).slice(0,3);
  atPerson=Object.entries(qT).sort((a,b)=>b[1]-a[1]).slice(0,4);
}catch(e){ atPage=null; atPerson=null; }
const fmt=n=>(n===null||n===undefined)?'—':Number(n).toLocaleString('en-US');
const now=new Date(Date.now()+8*3600*1000);
const MON=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const date=now.getUTCDate()+' '+MON[now.getUTCMonth()];
const D='\n━━━━━━━━━━\n';
const AT=id=>'<at user_id="'+id+'"></at>';
const MIKE=AT('ou_2cf32d2d9d8621cb8d46a9710ca351df');
const IMAN=AT('ou_110617a92012d59c85ad5b46399556af');
const THAD=AT('ou_f9c0415b83474af74a1e6a141a9b7f4d');
const RATNA=AT('ou_20bb893420d181bf0ce86ff4f9445f71');
const mkList=(arr,suf)=>{ if(arr===null) return '• Could not read.'; if(arr.length===0) return '• None right now. ✅'; return arr.map(function(e){return '• '+e[0]+' — '+e[1]+suf;}).join('\n'); };
const personLine=mkList(atPerson,' overdue');
const pageLine=mkList(atPage,' overdue');
const t='📋 M&D MANAGER UPDATE · '+date
+D+'🚨 THE BOTTLENECK\nStrategist QC — '+fmt(qc)+' videos held by 2 strategists (Wendi + Audrey).\n➡️ '+IMAN+' add a 3rd reviewer or clear it today — it gates the whole line.'
+D+'🧭 MARKETING COORDINATOR (whole-dept output)\n• Waiting at approval gates: '+fmt(gates)+'\n• Dept overdue: '+fmt(ov)+'  ·  Unscheduled to post: '+fmt(unsched)+'\n➡️ '+MIKE+' coordinate across functions + clear approvals — you own the department output today.'
+D+'⏰ OVERDUE — WHO IS HOLDING MOST\n'+personLine+'\n➡️ Respective managers: chase your people above.'
+D+'👤 PRODUCERS\n• In queue now: '+fmt(src)+'\n• Shoots booked ahead: '+fmt(rts)+'\n➡️ '+THAD+' keep sourcing + booking ahead — this feeds everything downstream.'
+D+'👤 STRATEGISTS — Wendi + Audrey\n• QC queue now: '+fmt(qc)+' ⚠️\n• In planning ahead: '+fmt(plan)+'\n➡️ '+IMAN+' clear QC first — it is the jam.'
+D+'👤 EDITORS\n• Editing now: '+fmt(edit)+'\n• Waiting to edit: '+fmt(rte)+'\n➡️ '+IMAN+' keep clearing as drafts land.'
+D+'👤 SMM\n• Ready to post: '+fmt(ready)+' (backlog OK)\n• Unscheduled — no upload date: '+fmt(unsched)+' ⚠️\n➡️ '+MIKE+' set an upload date on the unscheduled ones — that is the real problem, not the backlog.'
+D+'🎠 CAROUSELS (copywriting pipeline)\n• Not started: '+fmt(cNs)+'\n• Copywriting now: '+fmt(cCw)+'\n• Final approval: '+fmt(cFa)+'\n• Ready to post: '+fmt(cReady)+'\n• Overdue: '+fmt(cOv)+' ⚠️\n➡️ '+RATNA+' clear copy + approvals so carousels ship.'
+D+'🚩 PAGES AT RISK (most overdue)\n'+pageLine
+D+'📊 OVERALL\n• Not started: '+fmt(ns)+'  ·  Overdue: '+fmt(ov)
+'\n\n— Auto from the M&D base. Reply for detail.';
return [{ json: { content: JSON.stringify({text:t}), token } }];
